replace_once('custom_components/sbc5_control_center/sensor.py','''SENSOR_SPECS: tuple[SensorSpec, ...] = (\n    SensorSpec(unique_id="sbc5_cpu_temperature",''','''SENSOR_SPECS: tuple[SensorSpec, ...] = (\n    SensorSpec(unique_id="sbc5_ai_thermal_forecast_30s", name="SBC5 AI Thermal Forecast 30s", value_fn=lambda d: _predictor_number(d, "forecast_30s_c"), icon="mdi:thermometer-chevron-up", unit=UnitOfTemperature.CELSIUS, device_class=SensorDeviceClass.TEMPERATURE, state_class=SensorStateClass.MEASUREMENT),\n    SensorSpec(unique_id="sbc5_ai_thermal_forecast_60s", name="SBC5 AI Thermal Forecast 60s", value_fn=lambda d: _predictor_number(d, "forecast_60s_c"), icon="mdi:thermometer-chevron-up", unit=UnitOfTemperature.CELSIUS, device_class=SensorDeviceClass.TEMPERATURE, state_class=SensorStateClass.MEASUREMENT),\n    SensorSpec(unique_id="sbc5_ai_thermal_forecast_120s", name="SBC5 AI Thermal Forecast 120s", value_fn=lambda d: _predictor_number(d, "forecast_120s_c"), icon="mdi:thermometer-chevron-up", unit=UnitOfTemperature.CELSIUS, device_class=SensorDeviceClass.TEMPERATURE, state_class=SensorStateClass.MEASUREMENT),\n    SensorSpec(unique_id="sbc5_ai_thermal_predictor_confidence", name="SBC5 AI Thermal Predictor Confidence", value_fn=lambda d: _predictor_number(d, "confidence_percent"), icon="mdi:brain", unit=PERCENTAGE, state_class=SensorStateClass.MEASUREMENT),\n    SensorSpec(unique_id="sbc5_cpu_temperature",''')
replace_once('custom_components/sbc5_control_center/__init__.py','''from homeassistant.helpers import entity_registry as er\nfrom homeassistant.helpers import issue_registry as ir\n\nfrom .const import APP_VERSION, DOMAIN, LEGACY_DOMAIN, OLDER_LEGACY_DOMAIN, LEGACY_ENTITIES, PLATFORMS\n''','''from homeassistant.helpers import device_registry as dr\nfrom homeassistant.helpers import entity_registry as er\nfrom homeassistant.helpers import issue_registry as ir\n\nfrom .const import APP_VERSION, DEVICE_IDENTIFIER, DOMAIN, LEGACY_DOMAIN, OLDER_LEGACY_DOMAIN, LEGACY_ENTITIES, PLATFORMS\n''')
anchor='''def _remove_deprecated_native_update_entity(hass: HomeAssistant) -> None:\n'''
code='''PREDICTOR_NATIVE_IDS = {"sbc5_ai_thermal_forecast_30s", "sbc5_ai_thermal_forecast_60s", "sbc5_ai_thermal_forecast_120s", "sbc5_ai_thermal_predictor_confidence"}\n\ndef _migrate_predictor_template_entities(hass: HomeAssistant) -> None:\n    registry = er.async_get(hass)\n    overrides = hass.data.setdefault(DOMAIN, {}).setdefault("entity_id_overrides", {})\n    for unique_id in PREDICTOR_NATIVE_IDS:\n        canonical = f"sensor.{unique_id}"\n        for entry in list(registry.entities.values()):\n            if entry.unique_id == unique_id and entry.entity_id.startswith("sensor.") and entry.platform != DOMAIN:\n                overrides[unique_id] = canonical\n                registry.async_remove(entry.entity_id)\n\ndef _valid_mac(value: str) -> bool:\n    parts=(value or "").strip().lower().split(":")\n    return len(parts)==6 and all(len(p)==2 and all(c in "0123456789abcdef" for c in p) for p in parts) and value.lower()!="00:00:00:00:00:00"\n\ndef _reconcile_device_connections(hass: HomeAssistant, coordinator: SBC5Coordinator) -> None:\n    telemetry=getattr(getattr(coordinator,"data",None),"telemetry",None)\n    mac=(getattr(telemetry,"network_mac","") or "").strip().lower()\n    if not _valid_mac(mac): return\n    registry=dr.async_get(hass)\n    device=next((d for d in registry.devices.values() if (DOMAIN, DEVICE_IDENTIFIER) in d.identifiers),None)\n    if device is None: return\n    desired={(dr.CONNECTION_NETWORK_MAC,mac)}\n    if device.connections != desired:\n        registry.async_update_device(device.id,new_connections=desired)\n\n'''
replace_once('custom_components/sbc5_control_center/__init__.py',anchor,code+anchor)
replace_once('custom_components/sbc5_control_center/__init__.py','''    _remove_deprecated_native_update_entity(hass)\n    await _prepare_sbc5_namespace_registry(hass)\n    _canonicalize_native_entity_registry(hass)\n\n    coordinator = SBC5Coordinator(hass, entry)\n    await coordinator.async_config_entry_first_refresh()\n    entry.runtime_data = coordinator\n\n    await hass.config_entries.async_forward_entry_setups(entry, PLATFORMS)\n''','''    _remove_deprecated_native_update_entity(hass)\n    await _prepare_sbc5_namespace_registry(hass)\n    _migrate_predictor_template_entities(hass)\n    _canonicalize_native_entity_registry(hass)\n\n    coordinator = SBC5Coordinator(hass, entry)\n    await coordinator.async_config_entry_first_refresh()\n    entry.runtime_data = coordinator\n    _reconcile_device_connections(hass, coordinator)\n\n    await hass.config_entries.async_forward_entry_setups(entry, PLATFORMS)\n''')
